                        PyValue_CLOSE(tmp);
                        tmp = class_st;
                        class_st = PyValue_NULL;
                        IR_SET_TEMP(window[1], class_st);
                        PyValue_CLOSE(tmp);
                        tmp = global_super_st;
                        global_super_st = PyValue_NULL;
                        IR_SET_TEMP(window[0], global_super_st);
                        PyValue_CLOSE(tmp);
                        window[0] = PyValue_NULL;
                        window[1] = PyValue_NULL;
                        window[2] = PyValue_NULL;
